// Get HTML template
const template = $('html template').first().json.htmlTemplate;

// Get location and email from Airtable
const airtableData = $('Airtable Trigger').first().json.fields;
const location = airtableData.Location;
const email = airtableData.Email;

// Get images from Unsplash
const unsplashData = $('generate images of location').all(); // The Unsplash node
const image1 = unsplashData[0].json.results[0].urls.regular;
const image2 = unsplashData[0].json.results[1].urls.regular;
const image3 = unsplashData[0].json.results[2].urls.regular;

const  recommendations = $('organizing recommendations').all();
const  attractions = $('extract attractions from groq').all();

// Get map URL from static map HTTP request
const coords = $('store coordinates').first().json;
const mapUrl = `https://maps.geoapify.com/v1/staticmap?style=osm-bright&width=800&height=600&center=lonlat:${coords.coord1.lon},${coords.coord1.lat}&zoom=11&marker=lonlat:${coords.coord1.lon},${coords.coord1.lat};color:%23ff0000;size:medium|lonlat:${coords.coord2.lon},${coords.coord2.lat};color:%23ff0000;size:medium|lonlat:${coords.coord3.lon},${coords.coord3.lat};color:%23ff0000;size:medium&apiKey=4e0aa0a689d74a64bdc38a6ad6662f1c`;

// Replace placeholders in template
let finalHtml = template
  .replaceAll('{{LOCATION}}', location)
  .replace('{{IMAGE1}}', image1)
  .replace('{{IMAGE2}}', image2)
  .replace('{{IMAGE3}}', image3)
  .replace('{{RECOMMENDATION1}}', recommendations[0].json.recommendation1)
  .replace('{{RECOMMENDATION2}}', recommendations[0].json.recommendation2)
  .replace('{{RECOMMENDATION3}}', recommendations[0].json.recommendation3)
  .replace('{{Attraction1}}', attractions[0].json.attraction1)
  .replace('{{Attraction2}}', attractions[0].json.attraction2)
  .replace('{{Attraction3}}', attractions[0].json.attraction3)
  .replace('{{MAP_URL}}', mapUrl);

return [{
  json: {
    html: finalHtml,
    email: email
  }
}];

const groqOutput = $input.first().json.text || $input.first().json.output || $input.first().json.response;
const attractions = groqOutput.split('\n').filter(line => line.trim() !== '');

return [{ 
  json: { 
    attraction1: attractions[0],
    attraction2: attractions[1],
    attraction3: attractions[2]
  }
}];

